define(["app", "apps/candidates/view/candidatedashboardlayout_view", "apps/candidates/view/breadcrumbpanel_view",
        "apps/candidates/view/jobbannerpanel_view", "apps/candidates/view/candidatejobdesc_view",
        "apps/candidates/view/candidateemailshare_view", "validator", "i18nkeys", "moment", "bootstrap", "loadmask"],
    function (CandidateManager, Dashboard, BreadcrumbPanel, BannerPanel, JobDescriptionView, Emailshare, Validator, i18nkeys, moment) {
        CandidateManager.module("CandidatesApp.Description", function (JobDescription, CandidateManager, Backbone, Marionette, $, _) {

            JobDescription.Controller = {
                showDescription: function (token, source, jobSeq) {
                    if (source && (source === 'AGENCY' || source === 'CAMPUS')) {
                        CandidateManager.trigger("candidate:pagenotfound");
                    }
                    require(["entities/job", "entities/company"], function () {
                        var companyInfo, docData;
                        var candidateDashboard = new Dashboard.Layout();
                        var candidateDashboardPromise = candidateDashboard.setTemplate();
                        var onOff = new Object();
                        var emailShareModel = new Validator.Validator();
                        var i18nKeys = new i18nkeys.i18nEntity();
                        var name = getRefValue() + " " + "Job details";
                        ga('send', 'event', name);
                        $('.wrapper').unmask();
                        $('.wrapper').removeClass('page-height');
                        candidateDashboardPromise.done(function () {
                            CandidateManager.bodyRegion.show(candidateDashboard);
                        });
                        $('.wrapper').scrollTop(0);
                        var candidateDashboardModel = CandidateManager.request("job:entityByTokenJobSeq", token, jobSeq, source);
                        var companyModel = CandidateManager.request("company:entityByToken", token, source);

                        $.when(companyModel).done(function (companyinfo) {

                            //set company info i18next keys
                            companyinfo.set('i18nextKeys', i18nKeys.get('companyinfotpl'));

                            companyInfo = companyinfo;
                            onOff = companyinfo.attributes.config;

                            $.when(candidateDashboardModel).done(function (jobdescription) {

                                if ((!jobdescription) || (jobdescription.get("nonErLinkDeactivated"))) {
                                    CandidateManager.trigger("candidate:pagenotfound");
                                }else  if(jobdescription.get("linkDeactivated")){
                                    CandidateManager.trigger("candidate:pagelinkexpired");
                                } else {

                                    //seo fix
                                    var tempData = jobdescription.get("jobVO");
                                    docData = {
                                        companyName: companyInfo.get("companyName"),
                                        jobTitle: tempData.jobTitle,
                                        jobExp: tempData.jobReqExp,
                                        jobOpenings: tempData.numOfOpening,
                                        jobLocations: tempData.locations
                                    };
                                    CandidateManager.trigger("document:updateTitleDesc", docData, 'description');
                                    jobdescription.set('config', onOff);
                                    //set job description i18next keys
                                    jobdescription.set('i18nextKeys', i18nKeys.get('jobdescriptiontplkeys'));

                                    if ('breadcrumb_region' in CandidateManager.defaultConfig.get("config")) {
                                        var breadCrumbPanel = new BreadcrumbPanel.BreadcrumbPanel({model: jobdescription});
                                        var breadcrumbPromise = breadCrumbPanel.setTemplate();
                                        breadcrumbPromise.done(function () {
                                            candidateDashboard.breadcrumbRegion.show(breadCrumbPanel);
                                        });
                                    }

                                    if ('banner_region' in CandidateManager.defaultConfig.get("config")) {

                                        var comb = new Object();
                                        _.extend(comb, companyinfo.attributes);
                                        _.extend(comb, jobdescription.attributes);

                                        var bannerPanel = new BannerPanel.JobBannerPanel({model: new Backbone.Model(comb)});
                                        var bannerPromise = bannerPanel.setTemplate();
                                        bannerPromise.done(function () {
                                            candidateDashboard.bannerRegion.show(bannerPanel);
                                        });

                                        bannerPanel.on("emailShare", function (modelObj) {

                                            emailShareModel.set(modelObj.toJSON());
                                            var emailShare = new Emailshare.Email({model: emailShareModel});
                                            candidateDashboard.modalRegion.show(emailShare);
                                            Backbone.Validation.bind(emailShare);
                                        });

                                        bannerPanel.on("showalljobs", function () {
                                            CandidateManager.trigger("joblist:show", token, source);
                                        });
                                    }

                                    var jobDesc = new JobDescriptionView.JobDescription({model: jobdescription});
                                    var jobDescPromise = jobDesc.setTemplate();
                                    jobDescPromise.done(function () {
                                        candidateDashboard.midRegion.show(jobDesc);
                                    });

                                    jobDesc.on("jobapply", function (jobSeq) {
                                        CandidateManager.trigger("jobapplication:show", token, jobDesc.model.get("jobVO").jobSeq, source);
                                    });
                                    jobDesc.on("emailShare", function (modelObj) {

                                        emailShareModel.set(modelObj.toJSON());
                                        var emailShare = new Emailshare.Email({model: emailShareModel});
                                        candidateDashboard.modalRegion.show(emailShare);
                                        Backbone.Validation.bind(emailShare);
                                    });

                                    jobDesc.on("showalljobs", function () {
                                        CandidateManager.trigger("joblist:show", token, source);
                                    });

                                    if ('side_region' in CandidateManager.defaultConfig.get("config")) {
                                        require(["apps/candidates/view/candidatecompanyinfo_view"], function (Sidepanel) {
                                            var sidepanel = new Sidepanel.CompanyInfo({model: companyinfo});
                                            var sidePromise = sidepanel.setTemplate();
                                            sidePromise.done(function () {
                                                candidateDashboard.sideRegion.show(sidepanel);
                                            });
                                            sidepanel.on("jobapplyctp", function (jobSeq) {
                                                CandidateManager.trigger("jobapplication:show", token, onOff.ctpJobSeq);
                                            });

                                        });
                                    }
                                    CandidateManager.trigger("onlyonce");

                                    /* Google Job Posting */
                                    if(googleJobPosting) {
                                        let companyUrl = 'https://'+companyInfo.domainName;
                                        let companyLogoUrl = companyUrl+companyInfo.socialMediaLogoImage;
                                        let jobPostingDate = moment(tempData.jobPostingDate, 'DD-MMM-YYYY').format('YYYY-MM-DD');
                                        let jsonData = {
                                             "@context" : "https://schema.org/",
                                             "@type" : "JobPosting",
                                             "title" : tempData.jobTitle,
                                             "description" : tempData.jobDesc,
                                             "hiringOrganization" : {
                                                 "@type" : "Organization",
                                                 "name" : companyInfo.get('companyName'),
                                                 "sameAs" : companyUrl,
                                                 "logo" : companyLogoUrl
                                             },
                                             "datePosted": jobPostingDate,
                                             "jobLocation": {
                                                 "@type": "Place",
                                                 "address": {
                                                     "@type": "PostalAddress",
                                                     "streetAddress": "",
                                                     "addressLocality": "",
                                                     "addressRegion": tempData.jobLocation,
                                                     "postalCode": "",
                                                     "addressCountry": ""
                                                 }
                                             }
                                        };

                                        let scriptElement = document.getElementById('googleJobPostingScriptElement');
                                        if(!scriptElement) {
                                            scriptElement = document.createElement('script');
                                            scriptElement.setAttribute('id', 'googleJobPostingScriptElement');
                                            scriptElement.setAttribute('type', 'application/ld+json');
                                            document.head.appendChild(scriptElement);
                                        }
                                        scriptElement.innerText = JSON.stringify(jsonData);
                                    }
                                }
                            });
                        });
                    });
                },

                showDescriptionViewOnly: function (token, source, jobSeq) {
                    if (source && (source === 'AGENCY' || source === 'CAMPUS')) {
                        CandidateManager.trigger("candidate:pagenotfound");
                    }
                    require(["entities/job", "entities/company"], function () {
                        var companyInfo, docData;
                        var candidateDashboard = new Dashboard.Layout();
                        var candidateDashboardPromise = candidateDashboard.setTemplate();
                        var onOff = new Object();
                        var emailShareModel = new Validator.Validator();
                        var i18nKeys = new i18nkeys.i18nEntity();
                        var name = getRefValue() + " " + "Job details";
                        ga('send', 'event', name);
                        $('.wrapper').unmask();
                        $('.wrapper').removeClass('page-height');
                        candidateDashboardPromise.done(function () {
                            CandidateManager.bodyRegion.show(candidateDashboard);
                        });
                        $('.wrapper').scrollTop(0);
                        var candidateDashboardModel = CandidateManager.request("job:entityByTokenJobSeq", token, jobSeq, source);
                        var companyModel = CandidateManager.request("company:entityByToken", token, source);

                        $.when(companyModel).done(function (companyinfo) {

                            //set company info i18next keys
                            companyinfo.set('i18nextKeys', i18nKeys.get('companyinfotpl'));

                            companyInfo = companyinfo;
                            onOff = companyinfo.attributes.config;
                            onOff.showctp='N';
                            onOff.showviewall=false;
                            $.when(candidateDashboardModel).done(function (jobdescription) {

                                if ((!jobdescription) || (jobdescription.get("nonErLinkDeactivated"))) {
                                    CandidateManager.trigger("candidate:pagenotfound");
                                }else  if(jobdescription.get("linkDeactivated")){
                                    CandidateManager.trigger("candidate:pagelinkexpired");
                                } else {

                                    //seo fix
                                    var tempData = jobdescription.get("jobVO");
                                    docData = {
                                        companyName: companyInfo.get("companyName"),
                                        jobTitle: tempData.jobTitle,
                                        jobExp: tempData.jobReqExp,
                                        jobOpenings: tempData.numOfOpening,
                                        jobLocations: tempData.locations
                                    };
                                    CandidateManager.trigger("document:updateTitleDesc", docData, 'description');
                                    jobdescription.set('config', onOff);
                                    //set job description i18next keys
                                    jobdescription.set('i18nextKeys', i18nKeys.get('jobdescriptiontplkeys'));

                                    if ('breadcrumb_region' in CandidateManager.defaultConfig.get("config")) {
                                        var breadCrumbPanel = new BreadcrumbPanel.BreadcrumbPanel({model: jobdescription});
                                        var breadcrumbPromise = breadCrumbPanel.setTemplate();
                                        breadcrumbPromise.done(function () {
                                            candidateDashboard.breadcrumbRegion.show(breadCrumbPanel);
                                        });
                                    }

                                    if ('banner_region' in CandidateManager.defaultConfig.get("config")) {

                                        var comb = new Object();
                                        _.extend(comb, companyinfo.attributes);
                                        _.extend(comb, jobdescription.attributes);

                                        var bannerPanel = new BannerPanel.JobBannerPanel({model: new Backbone.Model(comb)});
                                        var bannerPromise = bannerPanel.setTemplate();
                                        bannerPromise.done(function () {
                                            candidateDashboard.bannerRegion.show(bannerPanel);
                                        });




                                    }
                                    jobdescription.set('enableLink', 'm');
                                    var jobDesc = new JobDescriptionView.JobDescriptionViewOnly({model: jobdescription});
                                    var jobDescPromise = jobDesc.setTemplate();
                                    jobDescPromise.done(function () {
                                        candidateDashboard.midRegion.show(jobDesc);
                                    });
                                    var jobDescview = new JobDescriptionView.JobDescription({model: jobdescription});
                                    var jobDescPromiseview = jobDescview.setTemplate();
                                    jobDescPromiseview.done(function () {
                                        candidateDashboard.midRegion.show(jobDescview);
                                    });
                                    jobDesc.on("jobapply", function (jobSeq) {
                                        CandidateManager.trigger("jobapplication:show", token, jobDesc.model.get("jobVO").jobSeq, source);
                                    });
                                    jobDesc.on("emailShare", function (modelObj) {

                                        emailShareModel.set(modelObj.toJSON());
                                        var emailShare = new Emailshare.Email({model: emailShareModel});
                                        candidateDashboard.modalRegion.show(emailShare);
                                        Backbone.Validation.bind(emailShare);
                                    });

                                    jobDesc.on("showalljobs", function () {
                                        CandidateManager.trigger("joblist:show", token, source);
                                    });

                                    if ('side_region' in CandidateManager.defaultConfig.get("config")) {
                                        require(["apps/candidates/view/candidatecompanyinfo_view"], function (Sidepanel) {
                                            var sidepanel = new Sidepanel.CompanyInfo({model: companyinfo});
                                            var sidePromise = sidepanel.setTemplate();
                                            sidePromise.done(function () {
                                               candidateDashboard.sideRegion.show(sidepanel);
                                            });
                                            sidepanel.on("jobapplyctp", function (jobSeq) {
                                                CandidateManager.trigger("jobapplication:show", token, onOff.ctpJobSeq);
                                            });

                                        });
                                    }
                                    CandidateManager.trigger("onlyonce");

                                    /* Google Job Posting */
                                    if(googleJobPosting) {
                                        let companyUrl = 'https://'+companyInfo.domainName;
                                        let companyLogoUrl = companyUrl+companyInfo.socialMediaLogoImage;
                                        let jobPostingDate = moment(tempData.jobPostingDate, 'DD-MMM-YYYY').format('YYYY-MM-DD');
                                        let jsonData = {
                                            "@context" : "https://schema.org/",
                                            "@type" : "JobPosting",
                                            "title" : tempData.jobTitle,
                                            "description" : tempData.jobDesc,
                                            "hiringOrganization" : {
                                                "@type" : "Organization",
                                                "name" : companyInfo.get('companyName'),
                                                "sameAs" : companyUrl,
                                                "logo" : companyLogoUrl
                                            },
                                            "datePosted": jobPostingDate,
                                            "jobLocation": {
                                                "@type": "Place",
                                                "address": {
                                                    "@type": "PostalAddress",
                                                    "streetAddress": "",
                                                    "addressLocality": "",
                                                    "addressRegion": tempData.jobLocation,
                                                    "postalCode": "",
                                                    "addressCountry": ""
                                                }
                                            }
                                        };

                                        let scriptElement = document.getElementById('googleJobPostingScriptElement');
                                        if(!scriptElement) {
                                            scriptElement = document.createElement('script');
                                            scriptElement.setAttribute('id', 'googleJobPostingScriptElement');
                                            scriptElement.setAttribute('type', 'application/ld+json');
                                            document.head.appendChild(scriptElement);
                                        }
                                        scriptElement.innerText = JSON.stringify(jsonData);
                                    }
                                }
                            });
                        });
                    });
                }
            }
        });
        return CandidateManager.CandidatesApp.Description.Controller;
    });
